import type {
	ActionBuilder,
	DataModelFromSchemaDefinition,
	GenericMutationCtx,
	MutationBuilder,
} from 'convex/server';
import type schema from '../schema';

import { internalActionGeneric, internalMutationGeneric } from 'convex/server';

// Test harness bindings, intentionally not generated by a live deployment.
// This directory marker also gives convex-test its fixture module root.

export type DataModel = DataModelFromSchemaDefinition<typeof schema>;
export type MutationCtx = GenericMutationCtx<DataModel>;
export const internalMutation = internalMutationGeneric as MutationBuilder<DataModel, 'internal'>;
export const internalAction = internalActionGeneric as ActionBuilder<DataModel, 'internal'>;
